PRMK.r(6370,[{"i":89642,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"11. Bertasbih Setelah Shalat Subuh","ar":"عَنْ أَبِي هُرَيْرَةَ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.","tr":"1 912- Dari Abu Hurairah RA, dia berkata, \"Rasulullah SAW bersabda, 'Barang siapa, ketika pagi dan sore, membaca doa; Maha Suci Allah dan segala puji bagi-Nya sebanyak seratus kali, maka pada hari kiamat tidak ada orang lain yang melebihi pahalanya kecuali orang yang juga pernah mengucapkan bacaan seperti itu atau lebih dari itu.'\" {Muslim 8/69}","path":"60/11.html","id":"muslim:60/11.html#2","sim":[[30414,100,"Kitab 9 Imam › Muslim No. 4858","kitab9"],[56571,100,"Kitab 9 Imam › Ahmad No. 8479","kitab9"],[56572,100,"Kitab 9 Imam › Ahmad No. 8480","kitab9"],[17978,96,"Riyadhus Shalihin No. 1448","riyadh"],[38938,96,"Kitab 9 Imam › Tirmidzi No. 3391","kitab9"],[100610,96,"Shahih Sunan Tirmidzi No. 3469","tirmidzi"]]},{"i":89643,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"12. Keutamaan Bertasbih","no":"1913","ar":"عَنْ أَبِي هُرَيْرَةَ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ ثَقِيلَتَانِ فِي الْمِيزَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ.","tr":"Dari Abu Hurairah RA, dia berkata, \"Rasulullah SAW telah bersabda, 'Dua kalimat yang ringan diucapkan tetapi berat timbangannya dan disenangi oleh Allah Subhanahu wa Ta'ala Yang Maha Pengasih yaitu, Subhaanallaah wa bihamdihi subhaanallaahil azhim {Maha Suci Allah dengan segala pujian-Nya dan Maha Suci Allah Yang Maha Agung}.'\" {Muslim 8/70}","path":"60/12.html","id":"muslim:60/12.html#1","dup":[[97334,"Shahih Sunan Ibnu Majah No. 3083-3874","ibnumajah"]],"sim":[[17931,100,"Riyadhus Shalihin No. 1405","riyadh"],[24736,100,"Kitab 9 Imam › Bukhari No. 6188","kitab9"],[30416,100,"Kitab 9 Imam › Muslim No. 4860","kitab9"],[38936,100,"Kitab 9 Imam › Tirmidzi No. 3389","kitab9"],[48885,100,"Kitab 9 Imam › Ibnu Majah No. 3796","kitab9"],[56780,100,"Kitab 9 Imam › Ahmad No. 6870","kitab9"],[100608,100,"Shahih Sunan Tirmidzi No. 3467","tirmidzi"],[24475,80,"Kitab 9 Imam › Bukhari No. 5927","kitab9"]]},{"i":89644,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"12. Keutamaan Bertasbih","no":"1914","ar":". عَنْ أَبِي هُرَيْرَةَ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ","tr":"Dari Abu Hurairah RA, dia berkata, \"Rasulullah SAW telah bersabda, 'Sesungguhnya Membaca doa, Maha Suci Allah, segala puji bagi Allah, tiada Tuhan selain Allah, dan Allah Maha Besar adalah lebih aku cintai daripada segala sesuatu yang ditampakkan oleh matahari.'' {Muslim 8/70}","path":"60/12.html","id":"muslim:60/12.html#2","sim":[[17932,100,"Riyadhus Shalihin No. 1406","riyadh"],[30417,100,"Kitab 9 Imam › Muslim No. 4861","kitab9"],[39068,100,"Kitab 9 Imam › Tirmidzi No. 3521","kitab9"],[100698,100,"Shahih Sunan Tirmidzi No. 3597","tirmidzi"],[65237,58,"Kitab 9 Imam › Ahmad No. 15816","kitab9"],[14974,44,"Bulughul Maram No. 306","bulughul"],[16241,44,"Bulughul Maram No. 1575","bulughul"],[17963,44,"Riyadhus Shalihin No. 1437","riyadh"]]},{"i":89645,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"13. Tahlil, Tahmid, dan Takbir","no":"1915","ar":"عن مُوسَى الْجُهَنِيّ عَنْ مُصْعَبِ بْنِ سَعْدٍ عَنْ أَبِيهِ قَالَ جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عَلِّمْنِي كَلَامًا أَقُولُهُ قَالَ قُلْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ قَالَ فَهَؤُلَاءِ لِرَبِّي فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَارْزُقْنِي قَالَ مُوسَى أَمَّا عَافِنِي فَأَنَا أَتَوَهَّمُ وَمَا أَدْرِي","tr":"Dari Musa Al Juhani, dari Mush'ab bin Sa'ad dari ayahnya RA, dia berkata, \"Pada suatu hari seorang Arab badui datang kepada Rasulullah SAW seraya berkata, 'Ya Rasulullah, ajarkanlah kepada saya suatu bacaan yang layak untuk saya baca!' Rasulullah SAW berkata, \"Ucapkanlah, Laa ilaaha illallaahu wahdahuu laa syariikalah. Allaahu akbaar kabiiran walhamdulillaahi katsiiran. Subhaanallaahi Rabbil 'aalamiin. Laa haula walaa quwwataa illaa billaahil 'aziizil hakiim {Tiada tuhan selain Allah, Yang Maha Esa, tidak ada sekutu bagi-Nya. Allah Maha Besar, segala puji bagi-Nya. Maha Suci Allah, Tuhan alam semesta. Tiada daya dan kekuatan kecuali dengan pertolongan Allah Yang Maha Perkasa dan Maha Bijaksana}. Orang Arab badui itu berkata, \"Ya Rasulullah, itukan bacaan yang ditujukan untuk Allah, lalu apa bacaan untuk diri saya?\" Rasulullah SAW bersabda, \"Allaahummaghfir lii warhamnii wahdinii warzuqnii.\" {Ya Allah, ampunilah aku, kasihanilah aku, tunjukkanlah aku, dan anugerahkanlah aku} Musa Al Juhani berkata, \"Saya meragukan kata-kata \"Aafini\" dan tidak tahu asal-usulnya.\" {Muslim 8/70}","path":"60/13.html","id":"muslim:60/13.html#1","sim":[[30418,100,"Kitab 9 Imam › Muslim No. 4862","kitab9"],[50946,83,"Kitab 9 Imam › Ahmad No. 1525","kitab9"],[17937,78,"Riyadhus Shalihin No. 1411","riyadh"],[50899,61,"Kitab 9 Imam › Ahmad No. 1478","kitab9"]]},{"i":89646,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"14. Ucapan yang Paling Disukai Allah SWT adalah, \"Subhanallah Wa","no":"1916","ar":"عَنْ أَبِي ذَرٍّ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلَا أُخْبِرُكَ بِأَحَبِّ الْكَلَامِ إِلَى اللَّهِ قُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِأَحَبِّ الْكَلَامِ إِلَى اللَّهِ فَقَالَ إِنَّ أَحَبَّ الْكَلَامِ إِلَى اللَّهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.","tr":"Dari Abu Dzarr RA, dia berkata, \"Rasulullah SAW pernah bertanya kepada saya, 'Hai Abu Dzarr, maukah kamu aku beritahukan tentang ucapan yang disenangi Allah?' Saya menjawab, \"Ya, saya mau ya Rasulullah. Beritahukanlah kepada saya tentang ucapan yang disenangi Allah.\" Kemudian beliau bersabda, \"Sesungguhnya ucapan yang paling disukai Allah Azza wa Jalla adalah Subhaanallahu wa bihamdih {Mahasuci Allah dengan segala puji bagi-Nya}\" {Muslim 8/86}","path":"60/14.html","intro":"Bihamdih\"","id":"muslim:60/14.html#1","sim":[[30467,100,"Kitab 9 Imam › Muslim No. 4911","kitab9"],[17935,71,"Riyadhus Shalihin No. 1409","riyadh"]]},{"i":89647,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"15. Orang yang Mengucapkan kalimat \"Laa Ilaaha Illallaahu Wahdahu Laa","no":"1917","ar":"عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ فِي يَوْمٍ مِائَةَ مَرَّةٍ كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ وَكَانَتْ لَهُ حِرْزًا مِنْ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ وَلَمْ يَأْتِ أَحَدٌ أَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ وَمَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ.","tr":"Dari Abu Hurairah RA, bahwasanya Rasulullah SAW telah bersabda, \"Barangsiapa yang mengucapkan 'Laa ilaaha illallaahu wahdah, laa syariikalahu lahul mulku wa lahul hamdu wa huwa 'alaa kulli syai'in qadiir' {Tiada tuhan selain Allah, Dialah Tuhan Yang Maha Esa. Tidak ada sekutu bagi-Nya, Dialah yang memiliki alam semesta dan segala puji hanya bagi-Nya. Allah adalah Maha Kuasa atas segala sesuatu} dalam sehari seratus kali, maka orang tersebut akan mendapat pahala sama seperti orang yang memerdekakan seratus orang budak, dicatat seratus kebaikan untuknya, dihapus seratus keburukan untuknya. Pada hari itu ia akan terjaga dari godaan syetan sampai sore hari dan tidak ada orang lain yang melebihi pahalanya, kecuali orang yang membaca lebih banyak dari itu. Barang siapa membaca Subhaanallaah wa bi hamdihi {Maha Suci Allah dan segala puji bagi-Nya} seratus kali dalam sehari, maka dosanya akan dihapus, meskipun sebanyak buih lautan.\" {Muslim 8/69}","path":"60/15.html","intro":"Syariikalahu\" Seratus Kali dalam Sehari","id":"muslim:60/15.html#1","sim":[[30413,100,"Kitab 9 Imam › Muslim No. 4857","kitab9"],[21598,92,"Kitab 9 Imam › Bukhari No. 3050","kitab9"],[76222,92,"Kitab 9 Imam › Malik No. 437","kitab9"],[83784,92,"Shahih Bukhari No. 3050","bukhari"],[57576,85,"Kitab 9 Imam › Ahmad No. 7666","kitab9"],[17933,76,"Riyadhus Shalihin No. 1407","riyadh"],[24474,73,"Kitab 9 Imam › Bukhari No. 5926","kitab9"],[57577,73,"Kitab 9 Imam › Ahmad No. 7667","kitab9"]]},{"i":89648,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"60. Kitab Dzikir","bab":"16. Orang yang Bertasbih Seratus Kali","no":"1918","ar":"عن سَعْدٍ قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ قَالَ يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ.","tr":"Dari Sa'ad bin Abu Waqqash RA, dia berkata, \"Kami pernah berada di sisi Rasulullah SAW. Setelah itu beliau bertanya, 'Apakah mampu salah seorang dari kalian memperoleh seribu kebaikan dalam sehari?' Lalu salah seorang dari para sahabat bertanya, \"Ya Rasulullah, bagaimana mungkin seseorang akan mampu meraih seribu kebaikan dalam sehari?\" Rasulullah berkata, \"Ketahuilah bahwa orang yang bertasbih seratus kali akan dicatat seribu kebaikan untuknya dan dihapus seribu kesalahan darinya.\" {Muslim 8/71}","path":"60/16.html","id":"muslim:60/16.html#1","sim":[[30422,100,"Kitab 9 Imam › Muslim No. 4866","kitab9"],[50948,93,"Kitab 9 Imam › Ahmad No. 1527","kitab9"],[50947,87,"Kitab 9 Imam › Ahmad No. 1526","kitab9"],[17954,83,"Riyadhus Shalihin No. 1428","riyadh"],[50901,70,"Kitab 9 Imam › Ahmad No. 1480","kitab9"],[100604,48,"Shahih Sunan Tirmidzi No. 3463","tirmidzi"],[38932,47,"Kitab 9 Imam › Tirmidzi No. 3385","kitab9"]]},{"i":89649,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"1. Berlindung Diri dari Keburukan Bencana dan Fitnah","no":"1919","ar":"عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهَؤُلَاءِ الدَّعَوَاتِ اللَّهُمَّ فَإِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ وَمِنْ شَرِّ فِتْنَةِ الْغِنَى وَمِنْ شَرِّ فِتْنَةِ الْفَقْرِ وَأَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ وَنَقِّ قَلْبِي مِنْ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنْ الدَّنَسِ وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اللَّهُمَّ فَإِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ وَالْهَرَمِ وَالْمَأْثَمِ وَالْمَغْرَمِ.","tr":"Dari Aisyah RA, bahwasanya Rasulullah SAW pernah membaca doa yang berbunyi, \"Ya Allah, sesungguhnya aku berlindung kepada-Mu dari fitnah api neraka dan siksanya, dari fitnah kubur dan siksanya, dari fitnah kekayaan, dari fitnah kefakiran, dan aku berlindung kepada-Mu ya Allah dari fitnah Dajjal. Ya Allah, hapuskanlah dosaku dengan air salju dan air embun, bersihkanlah hatiku dari segala kesalahan, sebagaimana Engkau bersihkan kain putih dari noda. Ya Allah, jauhkanlah antara aku dan dosaku sebagaimana Engkau jauhkan antara timur dengan barat.Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kemalasan dan kepikunan serta dari dosa dan lilitan hutang.\" {Muslim 8/79}","path":"61/01.html","id":"muslim:61/01.html#1","sim":[[30433,100,"Kitab 9 Imam › Muslim No. 4877","kitab9"],[72587,98,"Kitab 9 Imam › Ahmad No. 23166","kitab9"],[39488,88,"Kitab 9 Imam › An-Nasa'i No. 61","kitab9"],[39758,88,"Kitab 9 Imam › An-Nasa'i No. 331","kitab9"],[48917,77,"Kitab 9 Imam › Ibnu Majah No. 3828","kitab9"],[97361,77,"Shahih Sunan Ibnu Majah No. 3110-3906","ibnumajah"],[100627,76,"Shahih Sunan Tirmidzi No. 3495","tirmidzi"],[38964,73,"Kitab 9 Imam › Tirmidzi No. 3417","kitab9"]]},{"i":89650,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"2. Berlindung dari Kelemahan dan Kemalasan","no":"1920","ar":"عن أَنَس بْن مَالِكٍ قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْهَرَمِ وَالْبُخْلِ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ..","tr":"Dari Anas bin Malik RA, dia berkata, \"Rasulullah SAW pernah berdoa, 'Ya Allah, aku berlindung kepada-Mu dari kelemahan, kemalasan, rasa takut, kepikunan, dan kekikiran. Dan aku juga berlindung kepada-Mu dari siksa kubur serta bencana kehidupan dan kematian:\" {Muslim 8/75}","path":"61/02.html","id":"muslim:61/02.html#1","sim":[[30434,100,"Kitab 9 Imam › Muslim No. 4878","kitab9"],[18003,77,"Riyadhus Shalihin No. 1471","riyadh"],[21159,54,"Kitab 9 Imam › Bukhari No. 2611","kitab9"],[61128,54,"Kitab 9 Imam › Ahmad No. 12756","kitab9"],[44784,54,"Kitab 9 Imam › An-Nasa'i No. 5357","kitab9"],[24438,46,"Kitab 9 Imam › Bukhari No. 5890","kitab9"],[32234,46,"Kitab 9 Imam › Abu Dawud No. 1317","kitab9"],[91242,46,"Shahih Sunan Abu Dawud No. 1540","abudaud"]]},{"i":89651,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"3. Berlindung dari Takdir Buruk dan Kesialan","no":"1921","ar":"عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَعَوَّذُ مِنْ سُوءِ الْقَضَاءِ وَمِنْ دَرَكِ الشَّقَاءِ وَمِنْ شَمَاتَةِ الْأَعْدَاءِ وَمِنْ جَهْدِ الْبَلَاءِ قَالَ عَمْرٌو فِي حَدِيثِهِ قَالَ سُفْيَانُ أَشُكُّ أَنِّي زِدْتُ وَاحِدَةً مِنْهَا.","tr":"Dari Abu Hurairah RA, bahwasanya Rasulullah SAW pernah berdoa untuk berlindung dari takdir buruk, kesialan, dan kegembiraan musuh {karena kemalangan diri}, dan dari ujian yang berat. Amr mengatakan dalam haditsnya, \"Sufyan berkata, 'Saya merasa ragu bahwasanya saya telah menambah salah satu kata dalam hadits tersebut.\"' {Muslim 8/76}","path":"61/03.html","id":"muslim:61/03.html#1","sim":[[30436,100,"Kitab 9 Imam › Muslim No. 4880","kitab9"]]},{"i":89652,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"4. Berlindung dari Hilangnya Nikmat","no":"1922","ar":". عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ كَانَ مِنْ دُعَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ا للَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ","tr":"Dari Abdullah bin Umar RA, dia berkata, \"Di antara doa Rasulullah SAW adalah, 'Ya Allah, sesungguhnya aku berlindung kepada-Mu dari hilangnya kenikmatan yang telah Engkau berikan, dari lepasnya kesehatan yang telah Engkau anugerahkan, dari siksa-Mu yang datang secara tiba-tiba, dan dari segala kemurkaan-Mu'\" {Muslim 8/88-89}","path":"61/04.html","id":"muslim:61/04.html#1","sim":[[30478,89,"Kitab 9 Imam › Muslim No. 4922","kitab9"],[18007,73,"Riyadhus Shalihin No. 1475","riyadh"],[91247,73,"Shahih Sunan Abu Dawud No. 1545","abudaud"],[32238,56,"Kitab 9 Imam › Abu Dawud No. 1321","kitab9"],[16253,45,"Bulughul Maram No. 1587","bulughul"]]},{"i":89653,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"5. Menjawab ' Yarhamkumullah' untuk Orang yang Bersin, Jika Ia","no":"1923","ar":"عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ عَطَسَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ فَشَمَّتَ أَحَدَهُمَا وَلَمْ يُشَمِّتْ الْآخَرَ فَقَالَ الَّذِي لَمْ يُشَمِّتْهُ عَطَسَ فُلَانٌ فَشَمَّتَّهُ وَعَطَسْتُ أَنَا فَلَمْ تُشَمِّتْنِي قَالَ إِنَّ هَذَا حَمِدَ اللَّهَ وَإِنَّكَ لَمْ تَحْمَدْ اللَّهَ.","tr":"Dari Anas bin Malik RA, dia berkata, \"Pada suatu ketika ada dua orang laki-laki yang bersin di dekat Rasulullah SAW. Kemudian Rasulullah mengucapkan 'yarhakumullah' kepada salah seorang dari keduanya dan tidak mengucapkan yarhakumullah kepada yang lain. Lalu orang laki-laki yang tidak mendapat ucapan yarhakumullah dari Rasulullah tersebut berkata, \"Ya Rasulullah, tadi ketika si fulan bersin, engkau langsung mengucapkan yarhakumullah kepadanya. Tetapi, ketika saya bersin, mengapa engkau diam saja dan tidak mengucapkannya kepada saya?\" Maka Rasulullah SAW menjawab, \"Si fulan bersin dan ia membaca hamdalah, (memuji Allah Azza wa Jalla) sementara kamu tidak membaca hamdalah ketika bersin.' {Muslim 8/225}","path":"61/05.html","intro":"Mengucapkan Alhamdulillah","id":"muslim:61/05.html#1","sim":[[30863,100,"Kitab 9 Imam › Muslim No. 5307","kitab9"],[17304,67,"Riyadhus Shalihin No. 878","riyadh"],[100018,50,"Shahih Sunan Tirmidzi No. 2742","tirmidzi"],[38213,46,"Kitab 9 Imam › Tirmidzi No. 2666","kitab9"],[24305,40,"Kitab 9 Imam › Bukhari No. 5757","kitab9"]]},{"i":89654,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"61. Kitab Memohon Perlindungan","bab":"5. Menjawab ' Yarhamkumullah' untuk Orang yang Bersin, Jika Ia","no":"1924","ar":". عن إِيَاس بْن سَلَمَةَ بْنِ الْأَكْوَعِ أَنَّ أَبَاهُ حَدَّثَهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَطَسَ رَجُلٌ عِنْدَهُ فَقَالَ لَهُ يَرْحَمُكَ اللَّهُ ثُمَّ عَطَسَ أُخْرَى فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّجُلُ مَزْكُومٌ.","tr":"Dari Iyas bin Salamah bahwa ayahnya memberitahukan kepadanya, sesungguhnya dia mendengar Rasulullah SAW mengucapkan yarhakumullah ketika ada seorang laki-laki yang bersin di dekat beliau. Setelah itu, laki-laki tersebut bersin lagi dan Rasulullah SAW berkata, \"Orang itu sedang terserang flu.\" {Muslim 8/225}","path":"61/05.html","id":"muslim:61/05.html#2","sim":[[30865,100,"Kitab 9 Imam › Muslim No. 5309","kitab9"],[35337,67,"Kitab 9 Imam › Abu Dawud No. 4380","kitab9"],[94059,67,"Shahih Sunan Abu Dawud No. 5037","abudaud"],[65325,50,"Kitab 9 Imam › Ahmad No. 15904","kitab9"],[79925,50,"Kitab 9 Imam › Ad-Darimi No. 2546","kitab9"]]},{"i":89655,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"62. KItab Taubat","bab":"1. Perintah untuk Bertaubat","no":"1925","ar":"عَنْ أَبِي بُرْدَةَ قَالَ سَمِعْتُ الْأَغَرَّ وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحَدِّثُ ابْنَ عُمَرَ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ.","tr":"Dari Abu Burdah, dia berkata, \"Saya pernah mendengar Al Agharr, salah seorang sahabat Rasulullah, memberitahukan Ibnu Umar RA, bahwasanya Rasulullah bersabda, 'Wahai manusia, bertaubatlah kepada Allah, karena aku bertaubat seratus kali dalam sehari.'\" {Muslim 8/73}","path":"62/01.html","id":"muslim:62/01.html#1","sim":[[30427,100,"Kitab 9 Imam › Muslim No. 4871","kitab9"]]},{"i":89656,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"62. KItab Taubat","bab":"2. Dorongan untuk Bertaubat","no":"1926","ar":"عَنْ الْحَارِثِ بْنِ سُوَيْدٍ قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ أَعُودُهُ وَهُوَ مَرِيضٌ فَحَدَّثَنَا بِحَدِيثَيْنِ حَدِيثًا عَنْ نَفْسِهِ وَحَدِيثًا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ الْمُؤْمِنِ مِنْ رَجُلٍ فِي أَرْضٍ دَوِّيَّةٍ مَهْلِكَةٍ مَعَهُ رَاحِلَتُهُ عَلَيْهَا طَعَامُهُ وَشَرَابُهُ فَنَامَ فَاسْتَيْقَظَ وَقَدْ ذَهَبَتْ فَطَلَبَهَا حَتَّى أَدْرَكَهُ الْعَطَشُ ثُمَّ قَالَ أَرْجِعُ إِلَى مَكَانِيَ الَّذِي كُنْتُ فِيهِ فَأَنَامُ حَتَّى أَمُوتَ فَوَضَعَ رَأْسَهُ عَلَى سَاعِدِهِ لِيَمُوتَ فَاسْتَيْقَظَ وَعِنْدَهُ رَاحِلَتُهُ وَعَلَيْهَا زَادُهُ وَطَعَامُهُ وَشَرَابُهُ فَاللَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ الْعَبْدِ الْمُؤْمِنِ مِنْ هَذَا بِرَاحِلَتِهِ وَزَادِهِ","tr":"Dari Al Harits bin Suwaid, dia berkata, \"Saya pernah datang berkunjung ke rumah Abdullah untuk menjenguknya ketika ia sedang sakit. Lalu ia menuturkan kepada saya tentang dua hal; yang satu tentang dirinya dan yang satu lagi mengenai Rasulullah SAW.\" Abdullah berkata, \"Saya pernah mendengar Rasulullah SAW bersabda, 'Allah akan bergembira karena taubatnya seorang hamba yang beriman melebihi kegembiraan seseorang berada di gurun sahara yang mencekam dengan ditemani hewan tunggangannya serta perbekalan makanan dan minuman, kemudian ia tertidur. Ketika ia terbangun dari tidurnya, ternyata hewan tunggangannya terlepas dengan membawa perbekalan makanan dan minumannya. Kemudian orang tersebut mencari hewan tunggangannya tersebut ke sana dan kemari hingga ia merasa haus. Setelah itu, ia pun berkata, \"Sebaiknya aku kembali saja ke tempat tidurku semula sampai aku mati.\" Tak lama kemudian orang tersebut telah membaringkan tubuhnya dengan meletakkan kepalanya di atas lengannya dan bersiap-siap untuk mati. Ketika ia terbangun, ternyata hewan tunggangannya itu telah berada di sisinya dengan membawa bekal makanan dan minumannya. Sungguh kegembiraan Allah karena taubatnya seorang hamba-Nya yang beriman melebihi kegembiraan orang yang hewan tunggangannya terlepas lalu kembali dengan membawa perbekalan makanan dan minumannya.\" {Muslim 8/92}","path":"62/02.html","id":"muslim:62/02.html#1","sim":[[30485,100,"Kitab 9 Imam › Muslim No. 4929","kitab9"]]},{"i":89657,"src":"muslim","kind":"hadis","coll":"muslim","kitab":"62. KItab Taubat","bab":"3. Kesungguhan dalam Bertaubat dan Firman Allah SWT","no":"1927","ar":"عَنْ ابْنِ شِهَابٍ قَالَ ثُمَّ غَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ تَبُوكَ وَهُوَ يُرِيدُ الرُّومَ وَنَصَارَى الْعَرَبِ بِالشَّامِ قَالَ ابْنُ شِهَابٍ فَأَخْبَرَنِي عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ أَنَّ عَبْدَ اللَّهِ بْنَ كَعْبٍ كَانَ قَائِدَ كَعْبٍ مِنْ بَنِيهِ حِينَ عَمِيَ قَالَ سَمِعْتُ كَعْبَ بْنَ مَالِكٍ يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ قَالَ كَعْبُ بْنُ مَالِكٍ لَمْ أَتَخَلَّفْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ غَزَاهَا قَطُّ إِلَّا فِي غَزْوَةِ تَبُوكَ غَيْرَ أَنِّي قَدْ تَخَلَّفْتُ فِي غَزْوَةِ بَدْرٍ وَلَمْ يُعَاتِبْ أَحَدًا تَخَلَّفَ عَنْهُ إِنَّمَا خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ يُرِيدُونَ عِيرَ قُرَيْشٍ حَتَّى جَمَعَ اللَّهُ بَيْنَهُمْ وَبَيْنَ عَدُوِّهِمْ عَلَى غَيْرِ مِيعَادٍ وَلَقَدْ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ الْعَقَبَةِ حِينَ تَوَاثَقْنَا عَلَى الْإِسْلَامِ وَمَا أُحِبُّ أَنَّ لِي بِهَا مَشْهَدَ بَدْرٍ وَإِنْ كَانَتْ بَدْرٌ أَذْكَرَ فِي النَّاسِ مِنْهَا وَكَانَ مِنْ خَبَرِي حِينَ تَخَلَّفْتُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ أَنِّي لَمْ أَكُنْ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْهُ فِي تِلْكَ الْغَزْوَةِ وَاللَّهِ مَا جَمَعْتُ قَبْلَهَا رَاحِلَتَيْنِ قَطُّ حَتَّى جَمَعْتُهُمَا فِي تِلْكَ الْغَزْوَةِ فَغَزَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَرٍّ شَدِيدٍ وَاسْتَقْبَلَ سَفَرًا بَعِيدًا وَمَفَازًا وَاسْتَقْبَلَ عَدُوًّا كَثِيرًا فَجَلَا لِلْمُسْلِمِينَ أَمْرَهُمْ لِيَتَأَهَّبُوا أُهْبَةَ غَزْوِهِمْ فَأَخْبَرَهُمْ بِوَجْهِهِمْ الَّذِي يُرِيدُ وَالْمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَثِيرٌ وَلَا يَجْمَعُهُمْ كِتَابُ حَافِظٍ يُرِيدُ بِذَلِكَ الدِّيوَانَ قَالَ كَعْبٌ فَقَلَّ رَجُلٌ يُرِيدُ أَنْ يَتَغَيَّبَ يَظُنُّ أَنَّ ذَلِكَ سَيَخْفَى لَهُ مَا لَمْ يَنْزِلْ فِيهِ وَحْيٌ مِنْ اللَّهِ عَزَّ وَجَلَّ وَغَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِلْكَ الْغَزْوَةَ حِينَ طَابَتْ الثِّمَارُ وَالظِّلَالُ فَأَنَا إِلَيْهَا أَصْعَرُ فَتَجَهَّزَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ مَعَهُ وَطَفِقْتُ أَغْدُو لِكَيْ أَتَجَهَّزَ مَعَهُمْ فَأَرْجِعُ وَلَمْ أَقْضِ شَيْئًا وَأَقُولُ فِي نَفْسِي أَنَا قَادِرٌ عَلَى ذَلِكَ إِذَا أَرَدْتُ فَلَمْ يَزَلْ ذَلِكَ يَتَمَادَى بِي حَتَّى اسْتَمَرَّ بِالنَّاسِ الْجِدُّ فَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَادِيًا وَالْمُسْلِمُونَ مَعَهُ وَلَمْ أَقْضِ مِنْ جَهَازِي شَيْئًا ثُمَّ غَدَوْتُ فَرَجَعْتُ وَلَمْ أَقْضِ شَيْئًا فَلَمْ يَزَلْ ذَلِكَ يَتَمَادَى بِي حَتَّى أَسْرَعُوا وَتَفَارَطَ الْغَزْوُ فَهَمَمْتُ أَنْ أَرْتَحِلَ فَأُدْرِكَهُمْ فَيَا لَيْتَنِي فَعَلْتُ ثُمَّ لَمْ يُقَدَّرْ ذَلِكَ لِي فَطَفِقْتُ إِذَا خَرَجْتُ فِي النَّاسِ بَعْدَ خُرُوجِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْزُنُنِي أَنِّي لَا أَرَى لِي أُسْوَةً إِلَّا رَجُلًا مَغْمُوصًا عَلَيْهِ فِي النِّفَاقِ أَوْ رَجُلًا مِمَّنْ عَذَرَ اللَّهُ مِنْ الضُّعَفَاءِ وَلَمْ يَذْكُرْنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَلَغَ تَبُوكَ فَقَالَ وَهُوَ جَالِسٌ فِي الْقَوْمِ بِتَبُوكَ مَا فَعَلَ كَعْبُ بْنُ مَالِكٍ قَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ يَا رَسُولَ اللَّهِ حَبَسَهُ بُرْدَاهُ وَالنَّظَرُ فِي عِطْفَيْهِ فَقَالَ لَهُ مُعَاذُ بْنُ جَبَلٍ بِئْسَ مَا قُلْتَ وَاللَّهِ يَا رَسُولَ اللَّهِ مَا عَلِمْنَا عَلَيْهِ إِلَّا خَيْرًا فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيْنَمَا هُوَ عَلَى ذَلِكَ رَأَى رَجُلًا مُبَيِّضًا يَزُولُ بِهِ السَّرَابُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنْ أَبَا خَيْثَمَةَ فَإِذَا هُوَ أَبُو خَيْثَمَةَ الْأَنْصَارِيُّ وَهُوَ الَّذِي تَصَدَّقَ بِصَاعِ التَّمْرِ حِينَ لَمَزَهُ الْمُنَافِقُونَ فَقَالَ كَعْبُ بْنُ مَالِكٍ فَلَمَّا بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ تَوَجَّهَ قَافِلًا مِنْ تَبُوكَ حَضَرَنِي بَثِّي فَطَفِقْتُ أَتَذَكَّرُ الْكَذِبَ وَأَقُولُ بِمَ أَخْرُجُ مِنْ سَخَطِهِ غَدًا وَأَسْتَعِينُ عَلَى ذَلِكَ كُلَّ ذِي رَأْيٍ مِنْ أَهْلِي فَلَمَّا قِيلَ لِي إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَظَلَّ قَادِمًا زَاحَ عَنِّي الْبَاطِلُ حَتَّى عَرَفْتُ أَنِّي لَنْ أَنْجُوَ مِنْهُ بِشَيْءٍ أَبَدًا فَأَجْمَعْتُ صِدْقَهُ وَصَبَّحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَادِمًا وَكَانَ إِذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالْمَسْجِدِ فَرَكَعَ فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ لِلنَّاسِ فَلَمَّا فَعَلَ ذَلِكَ جَاءَهُ الْمُخَلَّفُونَ فَطَفِقُوا يَعْتَذِرُونَ إِلَيْهِ وَيَحْلِفُونَ لَهُ وَكَانُوا بِضْعَةً وَثَمَانِينَ رَجُلًا فَقَبِلَ مِنْهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَانِيَتَهُمْ وَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ وَوَكَلَ سَرَائِرَهُمْ إِلَى اللَّهِ حَتَّى جِئْتُ فَلَمَّا سَلَّمْتُ تَبَسَّمَ تَبَسُّمَ الْمُغْضَبِ ثُمَّ قَالَ تَعَالَ فَجِئْتُ أَمْشِي حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ فَقَالَ لِي مَا خَلَّفَكَ أَلَمْ تَكُنْ قَدْ ابْتَعْتَ ظَهْرَكَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي وَاللَّهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ أَنِّي سَأَخْرُجُ مِنْ سَخَطِهِ بِعُذْرٍ وَلَقَدْ أُعْطِيتُ جَدَلًا وَلَكِنِّي وَاللَّهِ لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ الْيَوْمَ حَدِيثَ كَذِبٍ تَرْضَى بِهِ عَنِّي لَيُوشِكَنَّ اللَّهُ أَنْ يُسْخِطَكَ عَلَيَّ وَلَئِنْ حَدَّثْتُكَ حَدِيثَ صِدْقٍ تَجِدُ عَلَيَّ فِيهِ إِنِّي لَأَرْجُو فِيهِ عُقْبَى اللَّهِ وَاللَّهِ مَا كَانَ لِي عُذْرٌ وَاللَّهِ مَا كُنْتُ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا هَذَا فَقَدْ صَدَقَ فَقُمْ حَتَّى يَقْضِيَ اللَّهُ فِيكَ فَقُمْتُ وَثَارَ رِجَالٌ مِنْ بَنِي سَلِمَةَ فَاتَّبَعُونِي فَقَالُوا لِي وَاللَّهِ مَا عَلِمْنَاكَ أَذْنَبْتَ ذَنْبًا قَبْلَ هَذَا لَقَدْ عَجَزْتَ فِي أَنْ لَا تَكُونَ اعْتَذَرْتَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا اعْتَذَرَ بِهِ إِلَيْهِ الْمُخَلَّفُونَ فَقَدْ كَانَ كَافِيَكَ ذَنْبَكَ اسْتِغْفَارُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَكَ قَالَ فَوَاللَّهِ مَا زَالُوا يُؤَنِّبُونَنِي حَتَّى أَرَدْتُ أَنْ أَرْجِعَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُكَذِّبَ نَفْسِي قَالَ ثُمَّ قُلْتُ لَهُمْ هَلْ لَقِيَ هَذَا مَعِي مِنْ أَحَدٍ قَالُوا نَعَمْ لَقِيَهُ مَعَكَ رَجُلَانِ قَالَا مِثْلَ مَا قُلْتَ فَقِيلَ لَهُمَا مِثْلَ مَا قِيلَ لَكَ قَالَ قُلْتُ مَنْ هُمَا قَالُوا مُرَارَةُ بْنُ الرَّبِيعَةَ الْعَامِرِيُّ وَهِلَالُ بْنُ أُمَيَّةَ الْوَاقِفِيُّ قَالَ فَذَكَرُوا لِي رَجُلَيْنِ صَالِحَيْنِ قَدْ شَهِدَا بَدْرًا فِيهِمَا أُسْوَةٌ قَالَ فَمَضَيْتُ حِينَ ذَكَرُوهُمَا لِي قَالَ وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمِينَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ مِنْ بَيْنِ مَنْ تَخَلَّفَ عَنْهُ قَالَ فَاجْتَنَبَنَا النَّاسُ وَقَالَ تَغَيَّرُوا لَنَا حَتَّى تَنَكَّرَتْ لِي فِي نَفْسِيَ الْأَرْضُ فَمَا هِيَ بِالْأَرْضِ الَّتِي أَعْرِفُ فَلَبِثْنَا عَلَى ذَلِكَ خَمْسِينَ لَيْلَةً فَأَمَّا صَاحِبَايَ فَاسْتَكَانَا وَقَعَدَا فِي بُيُوتِهِمَا يَبْكِيَانِ وَأَمَّا أَنَا فَكُنْتُ أَشَبَّ الْقَوْمِ وَأَجْلَدَهُمْ فَكُنْتُ أَخْرُجُ فَأَشْهَدُ الصَّلَاةَ وَأَطُوفُ فِي الْأَسْوَاقِ وَلَا يُكَلِّمُنِي أَحَدٌ وَآتِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُسَلِّمُ عَلَيْهِ وَهُوَ فِي مَجْلِسِهِ بَعْدَ الصَّلَاةِ فَأَقُولُ فِي نَفْسِي هَلْ حَرَّكَ شَفَتَيْهِ بِرَدِّ السَّلَامِ أَمْ لَا ثُمَّ أُصَلِّي قَرِيبًا مِنْهُ وَأُسَارِقُهُ النَّظَرَ فَإِذَا أَقْبَلْتُ عَلَى صَلَاتِي نَظَرَ إِلَيَّ وَإِذَا الْتَفَتُّ نَحْوَهُ أَعْرَضَ عَنِّي حَتَّى إِذَا طَالَ ذَلِكَ عَلَيَّ مِنْ جَفْوَةِ الْمُسْلِمِينَ مَشَيْتُ حَتَّى تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ وَهُوَ ابْنُ عَمِّي وَأَحَبُّ النَّاسِ إِلَيَّ فَسَلَّمْتُ عَلَيْهِ فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ فَقُلْتُ لَهُ يَا أَبَا قَتَادَةَ أَنْشُدُكَ بِاللَّهِ هَلْ تَعْلَمَنَّ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَسَكَتَ فَعُدْتُ فَنَاشَدْتُهُ فَسَكَتَ فَعُدْتُ فَنَاشَدْتُهُ فَقَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ فَفَاضَتْ عَيْنَايَ وَتَوَلَّيْتُ حَتَّى تَسَوَّرْتُ الْجِدَارَ فَبَيْنَا أَنَا أَمْشِي فِي سُوقِ الْمَدِينَةِ إِذَا نَبَطِيٌّ مِنْ نَبَطِ أَهْلِ الشَّامِ مِمَّنْ قَدِمَ بِالطَّعَامِ يَبِيعُهُ بِالْمَدِينَةِ يَقُولُ مَنْ يَدُلُّ عَلَى كَعْبِ بْنِ مَالِكٍ قَالَ فَطَفِقَ النَّاسُ يُشِيرُونَ لَهُ إِلَيَّ حَتَّى جَاءَنِي فَدَفَعَ إِلَيَّ كِتَابًا مِنْ مَلِكِ غَسَّانَ وَكُنْتُ كَاتِبًا فَقَرَأْتُهُ فَإِذَا فِيهِ أَمَّا بَعْدُ فَإِنَّهُ قَدْ بَلَغَنَا أَنَّ صَاحِبَكَ قَدْ جَفَاكَ وَلَمْ يَجْعَلْكَ اللَّهُ بِدَارِ هَوَانٍ وَلَا مَضْيَعَةٍ فَالْحَقْ بِنَا نُوَاسِكَ قَالَ فَقُلْتُ حِينَ قَرَأْتُهَا وَهَذِهِ أَيْضَا مِنْ الْبَلَاءِ فَتَيَامَمْتُ بِهَا التَّنُّورَ فَسَجَرْتُهَا بِهَا حَتَّى إِذَا مَضَتْ أَرْبَعُونَ مِنْ الْخَمْسِينَ وَاسْتَلْبَثَ الْوَحْيُ إِذَا رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينِي فَقَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ قَالَ فَقُلْتُ أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ قَالَ لَا بَلْ اعْتَزِلْهَا فَلَا تَقْرَبَنَّهَا قَالَ فَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ قَالَ فَقُلْتُ لِامْرَأَتِي الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الْأَمْرِ قَالَ فَجَاءَتْ امْرَأَةُ هِلَالِ بْنِ أُمَيَّةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ لَهُ يَا رَسُولَ اللَّهِ إِنَّ هِلَالَ بْنَ أُمَيَّةَ شَيْخٌ ضَائِعٌ لَيْسَ لَهُ خَادِمٌ فَهَلْ تَكْرَهُ أَنْ أَخْدُمَهُ قَالَ لَا وَلَكِنْ لَا يَقْرَبَنَّكِ فَقَالَتْ إِنَّهُ وَاللَّهِ مَا بِهِ حَرَكَةٌ إِلَى شَيْءٍ وَ وَاللَّهِ مَا زَالَ يَبْكِي مُنْذُ كَانَ مِنْ أَمْرِهِ مَا كَانَ إِلَى يَوْمِهِ هَذَا قَالَ فَقَالَ لِي بَعْضُ أَهْلِي لَوْ اسْتَأْذَنْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَتِكَ فَقَدْ أَذِنَ لِامْرَأَةِ هِلَالِ بْنِ أُمَيَّةَ أَنْ تَخْدُمَهُ قَالَ فَقُلْتُ لَا أَسْتَأْذِنُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا يُدْرِينِي مَاذَا يَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَأْذَنْتُهُ فِيهَا وَأَنَا رَجُلٌ شَابٌّ قَالَ فَلَبِثْتُ بِذَلِكَ عَشْرَ لَيَالٍ فَكَمُلَ لَنَا خَمْسُونَ لَيْلَةً مِنْ حِينَ نُهِيَ عَنْ كَلَامِنَا قَالَ ثُمَّ صَلَّيْتُ صَلَاةَ الْفَجْرِ صَبَاحَ خَمْسِينَ لَيْلَةً عَلَى ظَهْرِ بَيْتٍ مِنْ بُيُوتِنَا فَبَيْنَا أَنَا جَالِسٌ عَلَى الْحَالِ الَّتِي ذَكَرَ اللَّهُ عَزَّ وَجَلَّ مِنَّا قَدْ ضَاقَتْ عَلَيَّ نَفْسِي وَضَاقَتْ عَلَيَّ الْأَرْضُ بِمَا رَحُبَتْ سَمِعْتُ صَوْتَ صَارِخٍ أَوْفَي عَلَى سَلْعٍ يَقُولُ بِأَعْلَى صَوْتِهِ يَا كَعْبَ بْنَ مَالِكٍ أَبْشِرْ قَالَ فَخَرَرْتُ سَاجِدًا وَعَرَفْتُ أَنْ قَدْ جَاءَ فَرَجٌ قَالَ فَآذَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ بِتَوْبَةِ اللَّهِ عَلَيْنَا حِينَ صَلَّى صَلَاةَ الْفَجْرِ فَذَهَبَ النَّاسُ يُبَشِّرُونَنَا فَذَهَبَ قِبَلَ صَاحِبَيَّ مُبَشِّرُونَ وَرَكَضَ رَجُلٌ إِلَيَّ فَرَسًا وَسَعَى سَاعٍ مِنْ أَسْلَمَ قِبَلِي وَأَوْفَى الْجَبَلَ فَكَانَ الصَّوْتُ أَسْرَعَ مِنْ الْفَرَسِ فَلَمَّا جَاءَنِي الَّذِي سَمِعْتُ صَوْتَهُ يُبَشِّرُنِي فَنَزَعْتُ لَهُ ثَوْبَيَّ فَكَسَوْتُهُمَا إِيَّاهُ بِبِشَارَتِهِ وَاللَّهِ مَا أَمْلِكُ غَيْرَهُمَا يَوْمَئِذٍ وَاسْتَعَرْتُ ثَوْبَيْنِ فَلَبِسْتُهُمَا فَانْطَلَقْتُ أَتَأَمَّمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَلَقَّانِي النَّاسُ فَوْجًا فَوْجًا يُهَنِّئُونِي بِالتَّوْبَةِ وَيَقُولُونَ لِتَهْنِئْكَ تَوْبَةُ اللَّهِ عَلَيْكَ حَتَّى دَخَلْتُ الْمَسْجِدَ فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ فِي الْمَسْجِدِ وَحَوْلَهُ النَّاسُ فَقَامَ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ يُهَرْوِلُ حَتَّى صَافَحَنِي وَهَنَّأَنِي وَاللَّهِ مَا قَامَ رَجُلٌ مِنْ الْمُهَاجِرِينَ غَيْرُهُ قَالَ فَكَانَ كَعْبٌ لَا يَنْسَاهَا لِطَلْحَةَ قَالَ كَعْبٌ فَلَمَّا سَلَّمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ وَهُوَ يَبْرُقُ وَجْهُهُ مِنْ السُّرُورِ وَيَقُولُ أَبْشِرْ بِخَيْرِ يَوْمٍ مَرَّ عَلَيْكَ مُنْذُ وَلَدَتْكَ أُمُّكَ قَالَ فَقُلْتُ أَمِنْ عِنْدِكَ يَا رَسُولَ اللَّهِ أَمْ مِنْ عِنْدِ اللَّهِ فَقَالَ لَا بَلْ مِنْ عِنْدِ اللَّهِ وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سُرَّ اسْتَنَارَ وَجْهُهُ كَأَنَّ وَجْهَهُ قِطْعَةُ قَمَرٍ قَالَ وَكُنَّا نَعْرِفُ ذَلِكَ قَالَ فَلَمَّا جَلَسْتُ بَيْنَ يَدَيْهِ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ مِنْ تَوْبَتِي أَنْ أَنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ وَإِلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْسِكْ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ قَالَ فَقُلْتُ فَإِنِّي أُمْسِكُ سَهْمِيَ الَّذِي بِخَيْبَرَ قَالَ وَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ إِنَّمَا أَنْجَانِي بِالصِّدْقِ وَإِنَّ مِنْ تَوْبَتِي أَنْ لَا أُحَدِّثَ إِلَّا صِدْقًا مَا بَقِيتُ قَالَ فَوَاللَّهِ مَا عَلِمْتُ أَنَّ أَحَدًا مِنْ الْمُسْلِمِينَ أَبْلَاهُ اللَّهُ فِي صِدْقِ الْحَدِيثِ مُنْذُ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى يَوْمِي هَذَا أَحْسَنَ مِمَّا أَبْلَانِي اللَّهُ بِهِ وَاللَّهِ مَا تَعَمَّدْتُ كَذِبَةً مُنْذُ قُلْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى يَوْمِي هَذَا وَإِنِّي لَأَرْجُو أَنْ يَحْفَظَنِي اللَّهُ فِيمَا بَقِيَ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِنْ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّى إِذَا ضَاقَتْ عَلَيْهِمْ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ حَتَّى بَلَغَ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ قَالَ كَعْبٌ وَاللَّهِ مَا أَنْعَمَ اللَّهُ عَلَيَّ مِنْ نِعْمَةٍ قَطُّ بَعْدَ إِذْ هَدَانِي اللَّهُ لِلْإِسْلَامِ أَعْظَمَ فِي نَفْسِي مِنْ صِدْقِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أَكُونَ كَذَبْتُهُ فَأَهْلِكَ كَمَا هَلَكَ الَّذِينَ كَذَبُوا إِنَّ اللَّهَ قَالَ لِلَّذِينَ كَذَبُوا حِينَ أَنْزَلَ الْوَحْيَ شَرَّ مَا قَالَ لِأَحَدٍ وَقَالَ اللَّهُ سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انْقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِنْ تَرْضَوْا عَنْهُمْ فَإِنَّ اللَّهَ لَا يَرْضَى عَنْ الْقَوْمِ الْفَاسِقِينَ قَالَ كَعْبٌ كُنَّا خُلِّفْنَا أَيُّهَا الثَّلَاثَةُ عَنْ أَمْرِ أُولَئِكَ الَّذِينَ قَبِلَ مِنْهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حَلَفُوا لَهُ فَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ وَأَرْجَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْرَنَا حَتَّى قَضَى فِيهِ فَبِذَلِكَ قَالَ اللَّهُ عَزَّ وَجَلَّ وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا وَلَيْسَ الَّذِي ذَكَرَ اللَّهُ مِمَّا خُلِّفْنَا تَخَلُّفَنَا عَنْ الْغَزْوِ وَإِنَّمَا هُوَ تَخْلِيفُهُ إِيَّانَا وَإِرْجَاؤُهُ أَمْرَنَا عَمَّنْ حَلَفَ لَهُ وَاعْتَذَرَ إِلَيْهِ فَقَبِلَ مِنْهُ.","tr":"Dari Ibnu Syihab, dia berkata, \"Rasulullah SAW pernah berangkat ke perang Tabuk untuk menghadapi orang-orang Romawi dan orang-orang Arab yang beragama Nasrani di Syam.\" Ibnu Syihab berkata, \"Saya telah diceritakan oleh Abdurrahman bin Abdullah bin Ka'ab bin Malik, bahwa Abdullah bin Ka'ab bin Malik — Abdullah bin Ka'ab adalah salah seorang putra Ka'ab yang mendampingi Ka'ab ketika ia telah buta— berkata, 'Saya pernah mendengar Ka'ab bin Malik menceritakan peristiwa tentang dirinya ketika ia turut bersama Rasulullah SAW dalam perang Tabuk.' Ka'ab bin Malik berkata, \"Saya tidak pernah tertinggal menyertai Rasulullah SAW dalam peperangan yang beliau ikuti kecuali perang Tabuk, akan tetapi saya juga pernah tertinggal dalam perang Badar. Rasulullah SAW tidak pernah mencela seorang muslim yang tidak turut dalam perang Badar. Rasulullah SAW dan kaum muslimin hanya ingin menyerang rombongan kaum kafir Quraisy yang sedang berada dalam perjalanan dengan mengendarai unta, hingga Allah mempertemukan kaum muslimin dengan musuh mereka tanpa waktu yang disepakati sebelumnya. Saat itu saya ikut serta bersama Rasulullah pada malam Aqabah ketika kami berjanji untuk membela Islam. Menurut saya, turut serta dalam perang Badar tidak sebanding dengan turut serta dalam malam Aqabah, meskipun perang Badar lebih populer bagi kebanyakan orang. Di antara cerita ketika saya tidak turut serta bersama Rasulullah dalam perang Tabuk adalah sebagai berikut: \"Saya benar-benar tak berdaya dan tidak ada orang yang lebih banyak mempunyai keluasan daripada saya ketika saya tidak ikut serta dalam perang Tabuk tersebut. Demi Allah, sebelumnya saya tidak pernah menyiapkan dua ekor hewan tunggangan sama sekali dalam pelbagai peperangan. Tetapi dalam perang Tabuk ini, saya menyiapkan dua ekor hewan tunggangan. Akhirnya Rasulullah SAW pergi berangkat ke perang Tabuk pada saat cuaca sangat panas. Dapat dikatakan bahwasanya beliau menempuh perjalanan yang amat jauh dan penuh resiko serta menghadapi musuh yang berjumlah besar. Lalu Rasulullah SAW menjelaskan kepada kaum muslimin apa yang akan mereka hadapi bersamanya. Oleh karena itu, beliau memerintahkan kaum muslimin untuk mempersiapkan perbekalan perang yang cukup. Pada saat itu, kaum muslimin yang menyertai Rasulullah SAW banyak sekali tanpa ditunjuk melalui surat tugas untuk berperang. Ka'ab berkata, \"Ada seorang laki-laki yang tidak muncul karena ia ingin tidak turut serta berperang. Ia menduga bahwa ketidakturutannya itu tidak akan diketahui oleh Rasulullah SAW — selama tidak ada wahyu yang turun mengenai dirinya dari Allah Azza wa Jalla-. Rasulullah SAW pergi berangkat ke perang Tabuk ketika hasil panen buah sangat memuaskan, hingga saya harus memalingkan perhatian dari hasil panen tersebut. Rasulullah SAW dan kaum muslimin yang ikut serta sudah bersiap-siap dan saya pun segera pergi untuk mencari perbekalan bersama mereka. Lalu saya pulang tanpa memperoleh perbekalan sama sekali. Saya berkata dalam hati, \"Saya dapat mempersiapkan perbekalan sewaktu-waktu. Saya selalu dalam teka-teki antara ya dan tidak hingga orang-orang semakin siap.\" Rasulullah SAW berangkat bersama kaum muslimin, sedangkan saya belum mempersiapkan perbekalan sama sekali. Akhirnya saya pergi, lalu saya pulang tanpa mempersiapkan sesuatu. Saya senantiasa berada dalam kebimbangan seperti itu antara turut serta berperang ataupun tidak, hingga pasukan kaum muslimin telah bergegas berangkat dan perang pun berkecamuk sudah. Kemudian saya ingin menyusul ke medan pertempuran — tetapi hal itu hanyalah angan-angan— dan akhirnya saya ditakdirkan untuk tidak ikut serta ke medan perang. Setelah Rasulullah SAW pergi ke medan perang Tabuk, maka mulailah rasa sedih menyelimuti diri saya. Ketika keluar ke tengah-tengah masyarakat sekitar, saya menyadari bahwasanya tidak ada yang dapat saya temui kecuali orang-orang yang dalam kemunafikan atau orang-orang lemah yang diberikan uzur oleh Allah Azza wa Jalla. Sementara itu, Rasulullah SAW tidak mengingat diri saya hingga beliau sampai di Tabuk. Kemudian, ketika beliau sedang duduk-duduk di tengah para sahabat, tiba-tiba beliau bertanya, \"Mengapa Ka'ab bin Malik tidak ikut serta bersama kita?\" Seorang sahabat dari Bani Salimah menjawab, \"Ya Rasulullah, sepertinya Ka'ab bin Malik lebih mementingkan dirinya sendiri daripada perjuangan ini?\" Mendengar ucapan sahabat tersebut, Muadz bin Jabal berkata, \"Hai sahabat, buruk sekali ucapanmu itu! Demi Allah ya Rasulullah, saya tahu bahwasanya Ka'ab bin Malik itu adalah orang yang baik.\" Kemudian Rasulullah SAW diam. Ketika beliau terdiam seperti itu, tiba-tiba beliau melihat seorang laki-laki yang memakai helm besi yang sulit dikenali. Lalu Rasulullah SAW berkata, \"Kamu pasti Abu Khaitsamah?\" Ternyata orang tersebut adalah memang benar-benar Abu Khaitsamah Al Anshari, sahabat yang pernah menyedekahkan satu sha' kurma ketika ia dicaci maki oleh orang-orang munafik. Ka'ab bin Malik berkata, \"Ketika saya mendengar bahwasanya Rasulullah SAW telah bersiap-siap kembali dari perang Tabuk, maka saya pun diliputi kesedihan. Lalu saya mulai merancang alasan untuk berdusta. Saya berkata dalam hati, \"Alasan apa yang dapat menyelamatkan diri saya dari amarah Rasulullah?\" Untuk menghadapi hal tersebut, saya meminta pertolongan kepada keluarga yang dapat memberikan saran. Ketika ada seseorang yang berkata kepada saya bahwasanya Rasulullah SAW hampir tiba di kota Madinah, hilanglah alasan untuk berdusta dari benak saya. Akhirnya saya menyadari bahwasanya saya tidak dapat berbohong sedikitpun kepada Rasulullah SAW. Oleh karena itu, saya pun harus berkata jujur kepada beliau. Tak lama kemudian Rasulullah SAW tiba di kota Madinah. Seperti biasa, beliau langsung menuju masjid — manakala tiba dari bepergian ke suatu daerah— untuk melakukan shalat. Setelah melakukan shalat sunnah, Rasulullah SAW langsung bercengkrama bersama para sahabat. Setelah itu, datanglah beberapa orang sahabat yang tidak sempat ikut serta bertempur bersama kaum muslimin seraya menyampaikan berbagai alasan kepada beliau dengan bersumpah. Diperkirakan mereka yang tidak turut serta bertempur itu sekitar delapan puluh orang lebih. Ternyata Rasulullah menerima keterusterangan mereka yang tidak ikut serta berperang, membai'at mereka, memohon ampun untuk mereka, dan menyerahkan apa yang mereka sembunyikan dalam hati mereka kepada Allah. Selang beberapa saat kemudian, saya datang menemui Rasulullah SAW. Setelah saya memberi salam, beliau tersenyum seperti senyuman orang yang marah. Kemudian beliau pun berkata, \"Kemarilah!\" Lalu saya berjalan mendekati beliau hingga saya duduk tepat di hadapan beliau. Setelah itu Rasulullah SAW bertanya, \"Mengapa kamu tidak ikut serta bertempur bersama kami hai Ka'ab? Bukankah kamu telah berjanji untuk menyerahkan jiwa ragamu untuk Islam?\" Saya menjawab, \"Ya Rasulullah, demi Allah seandainya saya duduk di dekat orang selain diri engkau, niscaya saya yakin bahwasanya saya akan terbebaskan dari kemurkaannya karena alasan dan argumentasi yang saya sampaikan. Tetapi, demi Allah, saya tahu jika sekarang saya menyampaikan kepada engkau alasan yang penuh dusta hingga membuat engkau tidak marah, tentunya Allah lah yang membuat engkau marah kepada saya. Apabila saya mengemukakan kepada engkau ya Rasulullah alasan saya yang benar dan jujur, lalu engkau akan memarahi saya dengan alasan tersebut, maka saya pun akan menerimanya dengan senang hati. Biarkanlah Allah memberi hukuman kepada saya dengan ucapan saya yang jujur tersebut. Demi Allah, sesungguhnya tidak ada uzur yang membuat saya tidak ikut serta berperang. Demi Allah, saya tidak berdaya sama sekali kala itu meskipun saya mempunyai peluang yang sangat longgar sekali untuk ikut berjuang bersama kaum muslimin.\" Mendengar pengakuan yang tulus itu, Rasulullah pun berkata, \"Orang ini telah berkata jujur dan benar. Oleh karena itu, berdirilah hingga Allah memberimu keputusan.\" Akhirnya saya pun berdiri dan beranjak dari sisi beliau. Tak lama kemudian, ada beberapa orang dari Bani Salimah beramai-ramai mengikuti saya seraya berkata, \"Hai Ka'ab, demi Allah, sebelumnya kami tidak mengetahui bahwasanya kamu telah berbuat suatu kesalahan/dosa. Kamu benar-benar tidak dapat mengemukakan alasan kepada Rasulullah sebagaimana alasan yang dikemukakan para sahabat lain yang tidak turut berperang. Sesungguhnya, hanya istighfar Rasulullah untukmulah yang akan menghapus dosamu.\" Ka'ab bin Malik berkata setelah itu, \"Demi Allah, mereka selalu mencerca saya hingga saya ingin kembali lagi kepada Rasulullah SAW lalu saya dustakan diri saya.\" Ka'ab bin Malik berkata, \"Apakah ada orang lain yang telah menghadap Rasulullah SAW seperti diri saya ini?\" Orang-orang Bani Salimah menjawab, \"Ya. Ada dua orang lagi seperti dirimu. Kedua orang tersebut mengatakan kepada Rasulullah seperti apa yang telah kamu utarakan dan Rasulullah pun menjawabnya seperti jawaban kepadamu.\" Ka'ab bin Malik berkata, \"Lalu saya pun bertanya, 'Siapakah kedua orang tersebut hai para sahabat?' Mereka, kaum Bani Salimah, menjawab, \"Kedua orang tersebut adalah Murarah bin Rabi'ah Al Amin dan Hilal bin Umayyah Al Waqifi.\" Ka'ab bin Malik berkata, \"Kemudian mereka menyebutkan dua orang sahabat yang shalih yang ikut serta dalam perang Badar dan keduanya layak dijadikan suri tauladan yang baik. Setelah itu, saya pun berlalu ketika mereka menyebutkan dua orang tersebut kepada saya.\" Ka'ab bin Malik berkata, \"Beberapa hari kemudian, Rasulullah SAW melarang kaum muslimin untuk berbicara dengan kami bertiga yang tidak ikut serta dalam perang Tabuk. Sejak saat itu, kaum muslimin mulai menjauhi dan berubah sikap terhadap kami bertiga hingga bumi ini terasa asing bagi kami. Sepertinya, bumi ini bukanlah bumi yang pernah saya huni sebelumnya dan hal itu berlangsung lima puluh malam lamanya.\" Dua orang teman saya yang tidak ikut serta dalam perang Tabuk itu kini bersimpuh sedih di rumahnya sambil menangis, sedangkan saya adalah seorang anak muda yang tangguh dan tegar. Saya tetap bersikap wajar dan menjalankan aktivitas sehari-hari seperti biasanya. Saya tetap keluar dari rumah, pergi ke masjid untuk menghadiri shalat jama'ah bersama kaum muslimin lainnya, dan berjalan-jalan di pasar meskipun tidak ada seorang pun yang sudi berbicara dengan saya. Hingga pada suatu ketika saya menghampiri Rasulullah SAW sambil memberikan salam kepadanya ketika beliau berada di tempat duduknya usai shalat. Saya bertanya dalam hati, \"Apakah Rasulullah SAW akan menggerakkan bibirnya untuk menjawab salam ataukah tidak? Kemudian saya melaksanakan shalat di dekat Rasulullah sambil mencuri pandangan kepada beliau. Ketika saya telah siap untuk melaksanakan shalat, beliau memandang kepada saya. Dan ketika saya menoleh kepadanya, beliaupun mengalihkan pandangannya dari saya.\" Setelah lama terisolisir dari pergaulan kaum muslimin, saya pun pergi berjalan-jalan hingga sampai di pagar kebun Abu Qatadah. Abu Qatadah adalah putera paman saya {sepupu saya} dan ia adalah orang yang saya sukai. Sesampainya di sana, saya pun mengucapkan salam kepadanya. Tetapi, demi Allah, sama sekali ia tidak menjawab salam saya. Akhirnya saya memberanikan diri untuk bertanya kepadanya, \"Hai Abu Qatadah, saya bersumpah kepadamu dengan nama Allah, apakah kamu tidak mengetahui bahwasanya saya sangat mencintai Allah dan Rasul-Nya?\" Ternyata Abu Qatadah hanya terdiam saja. Lalu saya ulangi lagi ucapan saya dengan bersumpah seperti yang pertama kali. Namun ia tetap saja terdiam. Kemudian saya ulangi ucapan saya dan ia pun menjawab, \"Sesungguhnya Allah dan Rasul-Nya lebih mengetahui tentang hal ini.\" Mendengar ucapannya itu, berlinanglah air mata saya dan saya pun kembali ke rumah sambil menyusuri kebun tersebut. Ketika saya sedang berjalan-jalan di pasar Madinah, ada seorang laki-laki dari negeri Syam yang berjualan makanan di kota Madinah bertanya, \"Siapakah yang dapat menunjukkan kepada saya di mana Ka'ab bin Malik?\" Lalu orang-orang pun menunjukkan kepada saya hingga orang tersebut datang kepada saya sambil menyerahkan sepucuk surat kepada saya dari raja Ghassan. Karena saya dapat membaca dan menulis, maka saya pun memahami isi surat tersebut. Ternyata isi surat tersebut sebagai berikut, \"Kami mendengar bahwasanya temanmu {maksudnya adalah Rasulullah SAW} telah mengisolirmu dari pergaulan umum, sementara Tuhanmu sendiri tidaklah menyia-nyiakanmu seperti itu. Oleh karena itu, bergabunglah dengan kami, niscaya kami akan menolongmu.\" Selesai membaca surat itu, saya pun berkata, \"Sebenarnya surat ini juga merupakan sebuah bencana bagi saya.\" Lalu saya memasukannya ke dalam pembakaran dan membakarnya hingga musnah. Setelah empat puluh hari lamanya dari pengucilan umum, ternyata wahyu Tuhan pun tidak juga turun. Hingga pada suatu ketika, seorang utusan Rasulullah SAW mendatangi saya sambil menyampaikan sebuah pesan, \"Hai Ka'ab, sesungguhnya Rasulullah SAW memerintahkanmu untuk menghindari istrimu.\" Saya bertanya, \"Apakah saya harus menceraikan atau bagaimana?\" Utusan tersebut menjawab, \"Tidak usah kamu ceraikan. Tetapi, cukuplah kamu menghindarinya dan janganlah kamu mendekatinya.' Ka'ab bin Malik berkata, \"Ternyata, Rasulullah SAW juga telah mengutus utusan kepada dua orang teman saya yang tidak ikut serta dalam perang Tabuk dengan membawa pesan seperti yang disampaikan kepada saya.\" Lalu saya katakan kepada istri saya, 'Wahai dinda, sebaiknya dinda pulang terlebih dahulu ke rumah orang tua dinda dan tinggallah bersama dengan mereka hingga Allah memberikan keputusan yang jelas dalam permasalahan ini.' Ka'ab bin Malik berkata, \"Tak lama kemudian, istri Hilal bin Umayyah pergi mendatangi Rasulullah SAW sambil bertanya, 'Ya Rasulullah, Hilal bin Umayyah itu sudah lanjut usia dan lemah serta tidak mempunyai pembantu. Oleh karena itu, izinkanlah saya merawatnya.' Rasulullah SAW pun menjawab, \"Jangan. Sebaiknya kamu tidak usah menemaninya terlebih dahulu dan ia tidak boleh dekat denganmu untuk beberapa saat.\" Isteri Hilal tetap bersikeras dan berkata, \"Demi Allah ya Rasulullah, sekarang ia itu tidak mempunyai semangat hidup lagi. Ia senantiasa menangis, sejak mendapatkan permasalahan ini sampai sekarang.' Ka'ab bin Malik berkata, \"Beberapa orang dari keluarga saya berkata, 'Sebaiknya kamu meminta izin terlebih dahulu kepada Rasulullah dalam masalah istrimu ini. Karena Rasulullah SAW sendiri telah memberikan izin kepada istri Hilal bin Umayyah untuk merawat suaminya.' Ka'ab bin Malik berkata, \"Saya tidak akan meminta izin kepada Rasulullah SAW dalam persoalan istri saya ini. Karena, bagaimanapun, saya tidak akan tahu bagaimana jawaban Rasulullah nanti jika saya meminta izin kepada beliau sedangkan saya masih muda belia.\" Ka'ab bin Malik berkata, \"Ternyata hal itu berlangsung selama sepuluh malam hingga dengan demikian lengkaplah sudah lima puluh malam bagi kami terhitung sejak kaum muslimin dilarang untuk berbicara kepada kami. Ka'ab bin Malik berkata, \"Lalu saya melakukan shalat fajar pada malam yang ke lima puluh di bagian belakang rumah. Ketika saya sedang duduk dalam shalat tersebut, diri saya diliputi penyesalan dan kesedihan. Sepertinya bumi yang luas ini terasa sempit bagi diri saya. Tiba-tiba saya mendengar seseorang berteriak dengan lantangnya menembus cakrawala, \"Hai Ka'ab bin Malik, bergembiralah!\" Maka saya pun tersungkur sujud dan mengetahui bahwasanya saya telah terbebas dari persoalan saya. Ka'ab bin Malik berkata, \"Kemudian Rasulullah SAW mengumumkan kepada kaum muslimin usai shalat Shubuh bahwasanya Allah Subhanahu wa Ta'ala telah menerima taubat kami. Lalu orang-orang pun segera memberitahu kepada kami seraya mendatangi dua orang teman saya untuk memberitahukan kepada mereka berdua. Sementara itu, orang-orang dari Bani Aslam datang kepada saya dengan mengendarai kuda dan berjalan menyusuri gunung, sedangkan suara mereka lebih cepat dari kuda mereka. Ketika orang yang memberi kabar gembira itu telah datang kepada saya, maka saya pun segera melepaskan dua pakaian luar saya dan memakaikan kepadanya sebagai imbalan jasa pemberitahuannya kepada saya. Demi Allah, pada saat itu yang saya miliki hanyalah dua pakaian luar tersebut. Akhirnya saya meminjam dua pakaian {kepada seorang sahabat saya} dan langsung mengenakannya. Setelah itu, saya pun menghadap Rasulullah, sementara orang-orang berduyun-duyun menemui saya untuk memberikan ucapan selamat atas terkabulnya taubat saya. Lalu saya masuk ke dalam masjid di mana Rasulullah sedang duduk-duduk dan bercengkrama bersama para sahabat. Tiba-tiba Thalhah bin Ubaidillah berdiri dan berjalan mendekati saya serta menjabat tangan saya seraya mengucapkan selamat kepada saya. Demi Allah, pada saat itu tidak ada sahabat kaum Muhajirin yang berdiri untuk memberi selamat selain Thalhah. Perawi hadits berkata, 'Ka'ab tidak pernah melupakan penyambutan Thalhah tersebut.' Ka'ab berkata, \"Lalu saya memberi salam kepada Rasulullah SAW yang kala itu wajahnya terlihat berseri-seri. Tak lama kemudian beliau berkata, ' Bergembiralah hai Ka'ab, karena kamu mendapatkan sebaik-baik yang telah kamu lalui sejak kamu dilahirkan oleh ibumu.' Ka'ab berkata, \"Kemudian saya bertanya, 'Ya Rasulullah, apakah pengampunan untuk diri saya ini berasal dari engkau ataukah dari Allah?' Rasulullah menjawab, \"Dari Allah.\" Sesungguhnya, manakala Rasulullah SAW sedang senang, maka wajah beliau terlihat bersinar bagai bulan purnama dan kami pun mulai memahaminya. Ka'ab berkata, \"Ketika telah duduk di hadapan Rasulullah SAW, saya berkata, 'Ya Rasulullah, di antara rasa syukur diterimanya taubat saya, maka saya akan menyerahkan sebagian harta saya ini sebagai sedekah kepada Allah dan Rasul-Nya.' Rasulullah SAW menjawab, \"Hai Ka'ab, sisakanlah sebagian hartamu, maka yang demikian itu lebih baik untukmu.\" Akhirnya saya pun berkata, \"Baiklah. Saya akan menyisakan harta saya yang menjadi bagian saya di Khaibar.\" Saya berkata, \"Ya Rasulullah, sesungguhnya Allah Subhanahu wa Ta'ala telah menyelamatkan saya hanya karena kejujuran saya dan di antara taubat saya adalah bahwasanya saya tidak akan berbicara kecuali dengan sejujur-jujurnya selama sisa umur saya. Demi Allah, saya tidak tahu bahwasanya seorang muslim yang telah diuji Allah dalam kejujuran ucapannya sejak saya ceritakan hal ini kepada Rasulullah SAW hingga sekarang ini lebih baik daripada apa yang telah diujikan Allah kepada saya. Demi Allah, saya tidak ingin berdusta sejak saya ucapkan kata-kata ini kepada Rasulullah sampai sekarang. Selain itu saya pun selalu berharap semoga Allah memelihara saya dari kedustaan dalam sisa umur saya.\" Ka'ab bin Malik berkata, \"Akhirnya Allah Azza wa Jalla menurunkan ayat Al Qur'an yang berbunyi, Sesungguhnya Allah telah menerima taubat Nabi, orang-orang Muhajirin, dan orang-orang Anshar yang mengikuti Nabi dalam kesulitan setelah hati segolongan dari mereka hampir berpaling, kemudian Allah menerima taubat mereka. Sesungguhnya Allah itu Mahapengasih lagi Mahapenyayang kepada mereka dan terhadp tiga orang yang ditangguhkan penerimaan taubatnya hingga bila bumi telah menjadi sempit bagi mereka, padahal bumi itu luas dan jiwa mereka pun terasa sempit serta mereka telah mengetahui bahwasanya tidak ada tempat untuk berlindung dari siksa Allah melainkan kepada-Nya. Kemudian Allah menerima taubat mereka agar mereka tetap dalam taubatnya. Sesungguhnya Allahlah Yang Mahamenerima taubat lagi Mahapenyayang. Hai orang-orang yang beriman, bertakwalah kepada Allah dan hendaklah kamu bersama orang-orang yang jujur. {Qs. At-Taubah {9}: 117-119} Ka'ab berkata, \"Demi Allah, tidak ada nikmat yang telah diberikan Allah kepada saya, setelah Allah menunjukkan kepada saya Islam, yang saya anggap lebih besar daripada kejujuran. Seandainya saya berdusta, maka saya akan celaka sebagaimana orang-orang yang telah berdusta. Sesungguhnya Allah Subhanahu wa Ta'ala telah menyebutkan keburukan orang-orang yang berdusta ketika Allah menurunkan ayat yang berbunyi: Kelak mereka akan bersumpah kepadamu dengan nama Allah apabila kamu kembali kepada mereka supaya kamu berpaling dari mereka. Maka berpalinglah kamu dari mereka, karena sesungguhnya mereka itu najis dan tempat mereka adalah jahanam sebagai balasan dari apa yang telah mereka kerjakan. Mereka akan bersumpah kepadamu supaya kamu ridha kepada mereka, maka sesungguhnya Allah tidak ridah kepada orang-orang yang fasik itu. {Qs. At-Taubah {9}: 95-96} Ka'ab berkata kepada dua orang temannya, \"Kita bertiga ini adalah orang-orang yang tertinggal dari kelompok yang telah diterima Rasulullah SAW ketika mereka bersumpah, lalu beliau membai'at mereka dan memohonkan ampun untuk mereka. Ternyata Rasulullah menangguhkan persolan kita hingga ada keputusan dari Allah subhanahu wa Ta'ala tentang persoalan kita ini. Oleh karena itu, Allah Subhanahu wa Ta'ala telah berfirman: Dan terhadap tiga orang yang penerimaan taubat mereka ditangguhkan hingga bumi telah menjadi sempit bagi mereka, padahal bumi itu luas {Qs. At-Taubah {9}: 118} Ka'ab berkata, \"Apa yang disebutkan Allah dalam ayat ini bukankah tertinggalnya kami dari peperangan, melainkan tentang tertinggalnya kami dari kelompok orang-orang yang bersumpah dan beralasan kepada Rasulullah SAW, lalu beliau menerima alasan mereka. Setelah itu, Rasulullah menangguhkan persoalan kami hingga ada keputusan dari Allah Ta'ala. {Muslim 8/106-112}","path":"62/03.html","intro":"'Dan Terhadap Tiga Orang yang Ditangguhkan Penerimaan Taubatnya. '","id":"muslim:62/03.html#1","sim":[[30529,100,"Kitab 9 Imam › Muslim No. 4973","kitab9"],[16287,78,"Riyadhus Shalihin No. 21","riyadh"],[18064,78,"Riyadhus Shalihin No. 1527","riyadh"],[32800,78,"Kitab 9 Imam › Abu Dawud No. 1883","kitab9"],[91791,78,"Shahih Sunan Abu Dawud No. 2202","abudaud"],[40150,74,"Kitab 9 Imam › An-Nasa'i No. 723","kitab9"],[43191,74,"Kitab 9 Imam › An-Nasa'i No. 3764","kitab9"],[22148,71,"Kitab 9 Imam › Bukhari No. 3600","kitab9"]]}]);